CustomField.formula:
IF(
/*If Account is Country Parent, stores WL_Owner__c value */
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'), WL_Owner__c ,
IF(
/*If Account is Sales site, stores Country Parent Account's WL_Owner__c by traversing one level up the hierarchy*/
AND(ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'),NOT(ISBLANK(ParentId))), Parent.WL_Owner__c,WL_Owner__c))
